771→if (import.meta.url === `file://${process.argv[1]}`) {
772→  const [snapshotPath, toolCallPath, ...capturePaths] = process.argv.slice(2);
773→  if (!snapshotPath || !toolCallPath) {
774→    console.error("usage: node build-events.mjs <snapshot.json> <tool-call-logs.jsonl> [capture.jsonl ...]");
775→    process.exit(2);
776→  }
777→
778→  const snapshot = JSON.parse(readFileSync(snapshotPath, "utf8"));
779→  const toolCallRows = parseJsonl(readFileSync(toolCallPath, "utf8"));
780→  const captureEvents = capturePaths.flatMap((p) => parseJsonl(readFileSync(p, "utf8")));
781→
782→  const events = buildEvents({ snapshot, toolCallRows, captureEvents });
783→  const outPath = "evaluation/provenance/artifacts/provenance-events.jsonl";
784→  mkdirSync(dirname(outPath), { recursive: true });
785→  writeFileSync(outPath, events.map((e) => JSON.stringify(e)).join("\n") + "\n", "utf8");
