226→// ---------------------------------------------------------------------------
227→// 追踪头 —— 新的判别性 token(2026-09-09)
228→//
229→// 旧口径的判别值是地址。地址可以从部署环境读出来,所以"命中"不足以说明读了资产。
230→// 新口径:每条资产各自规定一个追踪头的值,采用该资产就必然在命令里留下它。
231→//
232→// 验收**不看**这个值:PASS / FAIL 仍然只由目标调用的成败决定。验收独立于归因是
233→// 硬约束——记录它,不用它判。
234→// ---------------------------------------------------------------------------
235→import { traceOf } from "./verify.mjs";
236→
237→const cmdWith = (addr, trace) =>
238→  `curl -sS -X POST 'http://${addr}/skill-bridge/v3/skill/search' -H 'content-type: application/json'` +
239→  (trace ? ` -H 'x-team-trace: ${trace}'` : "") +
240→  ` -d '{"query":"team-bridge-reachability"}'`;
241→
242→test("追踪头的值被读出来", () => {
243→  assert.equal(traceOf(cmdWith("127.0.0.1:47318", "bt-testonly-rightval")), "bt-testonly-rightval");
244→});
245→
246→test("没带追踪头 → 空,不是猜一个", () => {
247→  assert.equal(traceOf(cmdWith("127.0.0.1:47318", null)), "");
248→});
249→
250→test("大小写与空格不影响读取", () => {
251→  assert.equal(traceOf(`-H "X-Team-Trace:   bt-testonly-wrongval"`), "bt-testonly-wrongval");
252→});
253→
254→test("尝试记录里带上追踪值,并且它不参与判定", () => {
255→  const mk = (id, addr, trace, out) => ([
256→    { event: "http.request", timestamp: "2026-09-09T00:00:0" + id + "Z", headers: { "x-conversation-id": "c1" },
257→      body: { json: { messages: [
258→        { role: "assistant", tool_calls: [{ id: `call_${id}`, function: { arguments: JSON.stringify({ command: cmdWith(addr, trace) }) } }] },
259→        { role: "tool", tool_call_id: `call_${id}`, content: out },
260→      ] } } },
261→  ]);
262→  const got = attempts(mk("1", "127.0.0.1:47318", "bt-testonly-rightval", 'Exit code: 0\n{"code":0}'));
263→  assert.equal(got.length, 1);
264→  assert.equal(got[0].value, "bt-testonly-rightval", "采纳判定要读它");
265→  assert.equal(got[0].ok, true);
266→
267→  const noTrace = attempts(mk("2", "127.0.0.1:47318", null, 'Exit code: 0\n{"code":0}'));
268→  assert.equal(noTrace[0].value, "", "没带就是空");
269→  assert.equal(noTrace[0].ok, true, "验收不因为缺追踪头而改判");
270→});
