123→test("the service's own log separates them: one answered row in the call's window binds the envelope to the only reachable address, the curl 28 to the only unreachable one, and shell order makes the last one decide", () => {
124→  const cmd = `${curl(B, "bt-r")}\necho\n${curl(A, "bt-w")}`;
125→  const cap = session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}\nHTTP=000\nStderr: curl: (28) Connection timed out after 12003 milliseconds\nExit Code: 0` }] }]);
126→  const t0 = cap.find((e) => e.event === "http.response").timestamp;
127→  const rows = [intentRow(t0, cmd), answeredRow(t0, 100)];
128→  const r = verify(cap, { serviceRows: rows, reachability: REACH });
129→  assert.deepEqual(r.attempts.map((a) => [`${a.host}:${a.port}`, a.ok, a.why]), [["127.0.0.1:47318", true, "code 0"], ["10.244.7.19:8096", false, "timed out"]]);
130→  assert.ok(r.attempts[0].executed_at, "the answered request carries the service time");
131→  assert.equal(r.verdict, FAIL);
132→  assert.match(r.reason, /10\.244\.7\.19:8096/);
133→});
