159→    { command: curl(A, "bt-w", "-m 20"), result: "Stdout: \nStderr: curl: (28) Connection timed out after 20001 milliseconds\nExit code: 28" },
160→    { command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` },
161→  ], took: 20200 }]);
