 31→/** A CodeBuddy Bash tool result, in the exact shape both captures contain. */
 32→function bashResult({ command, stdout = "(empty)", stderr = "(empty)", exitCode = 0 }) {
 33→  return `Command: ${command}\nStdout: ${stdout}\nStderr: ${stderr}\nExit Code: ${exitCode}\nSignal: (none)`;
