 39→/**
 40→ * A captured session. Each step is one assistant message; `calls` are the tool
 41→ * calls it issued together, each with the command and the result text that came
 42→ * back. Timestamps follow batch 4: message k is produced at T0 + 10k seconds
 43→ * and its results are sent back 12 seconds later.
 44→ */
 45→function session(steps) {
 46→  const rows = [];
 47→  const messages = [{ role: "user", content: "do the task" }];
 48→  let t = Date.parse("2026-09-10T23:26:30Z");
 49→  let n = 0;
 50→  rows.push({ event: "http.request", requestId: "r0", timestamp: new Date(t).toISOString(), headers: { "x-conversation-id": "conv-1" }, body: { json: { messages: [...messages] } } });
 51→  for (const step of steps) {
 52→    t += 2000;
 53→    rows.push({ event: "http.response", requestId: `r${n}`, timestamp: new Date(t).toISOString(), body: { text: "" } });
 54→    const calls = step.calls.map((c, i) => ({ id: c.id ?? `c${n}_${i}`, ...c }));
 55→    messages.push({ role: "assistant", tool_calls: calls.map((c) => ({ id: c.id, function: { name: "Bash", arguments: JSON.stringify({ command: c.command }) } })) });
 56→    for (const c of calls) if (c.result !== undefined) messages.push({ role: "tool", tool_call_id: c.id, content: `Command: ${c.command}\n${c.result}` });
 57→    t += step.took ?? 12000; n += 1;
 58→    rows.push({ event: "http.request", requestId: `r${n}`, timestamp: new Date(t).toISOString(), headers: { "x-conversation-id": "conv-1" }, body: { json: { messages: [...messages] } } });
 59→  }
 60→  return rows;
 61→}
