  1→/**
  2→ * Acceptance tests.
  3→ *
  4→ * Each case is a rule that sounds reasonable and gets the verdict wrong: "some
  5→ * call returned 200", "it succeeded at some point", "it never failed", "there
  6→ * was no successful call so it failed".
  7→ */
  8→
  9→import { test } from "node:test";
 10→import assert from "node:assert/strict";
 11→
 12→import { verify, attempts, outcomeOfAttempt, PASS, FAIL, ERROR } from "./verify.mjs";
 13→
 14→import { TASK_MARKER } from "./verify.mjs";
 15→
 16→const TARGET_OK = "http://127.0.0.1:47318/skill-bridge/v3/skill/search";
 17→const TARGET_BAD = "http://10.244.7.19:8096/skill-bridge/v3/skill/search";
 18→const READ = "http://127.0.0.1:8096/skill-bridge/v3/skill/get-by-name";
 19→
 20→const OK_BODY = 'Stdout: {"code":0,"message":"ok","data":{"items":[]}}\nHTTP_CODE: 200';
 21→const TIMEOUT = "Exit code: 28\nStdout: \nStderr: curl: (28) Operation timed out after 75000 ms";
 22→
 23→/** The command the model wrote, as it appears in the tool call's arguments. */
 24→const cmdFor = (url, query) =>
 25→  JSON.stringify({ command: `curl -sSk -X POST ${url} -d '{"query":"${query}"}'` });
 26→
 27→/**
 28→ * A captured session. Each step is a call the model made, optionally with the
 29→ * result that came back — `body: null` means the result was never captured,
 30→ * which the attempt list has to survive.
 31→ */
 32→function session(steps) {
 33→  const messages = [{ role: "user", content: "do the task" }];
 34→  steps.forEach(({ url, body, query = TASK_MARKER }, i) => {
 35→    messages.push({
 36→      role: "assistant",
 37→      tool_calls: [{ id: `c${i}`, function: { name: "Bash", arguments: cmdFor(url, query) } }],
 38→    });
 39→    if (body !== null) {
 40→      messages.push({
 41→        role: "tool", tool_call_id: `c${i}`,
 42→        content: `Command: curl -sSk -X POST ${url} -d '{"query":"${query}"}'\n${body}`,
 43→      });
 44→    }
 45→  });
 46→  return [{
 47→    event: "http.request",
 48→    requestId: "req-1",
 49→    timestamp: "2026-09-05T12:00:00Z",
 50→    headers: { "x-conversation-id": "conv-1" },
 51→    body: { json: { messages } },
 52→  }];
 53→}
 54→
 55→// ── the four outcomes ─────────────────────────────────────────────
 56→
 57→test("a successful prerequisite read does not make a timed-out target pass", () => {
 58→  // "Some call in this session returned 200" is true here, and the 200 is the
 59→  // model fetching the asset that told it which address to use.
 60→  const r = verify(session([
 61→    { url: READ, body: OK_BODY },
 62→    { url: TARGET_BAD, body: TIMEOUT },
 63→  ]));
 64→  assert.equal(r.verdict, FAIL);
 65→  assert.equal(r.attempts.length, 1, "reading the asset is a bridge call too, but it is not the target");
 66→  assert.match(r.reason, /timed out/);
 67→});
 68→
 69→test("succeeding early and failing at the end is a failure", () => {
 70→  // "It succeeded at some point" is true and the run did not work.
 71→  const r = verify(session([
 72→    { url: TARGET_OK, body: OK_BODY },
 73→    { url: TARGET_OK, body: TIMEOUT },
 74→  ]));
 75→  assert.equal(r.verdict, FAIL);
 76→  assert.match(r.reason, /despite 1 earlier success/);
 77→});
 78→
 79→test("failing first and succeeding last is a pass", () => {
 80→  // "It never failed" is false and the run did work. Retrying after an error is
 81→  // ordinary behaviour; a rule that punishes it is measuring neatness.
 82→  const r = verify(session([
 83→    { url: TARGET_BAD, body: TIMEOUT },
 84→    { url: TARGET_OK, body: OK_BODY },
 85→  ]));
 86→  assert.equal(r.verdict, PASS);
 87→  assert.match(r.reason, /after 1 earlier failure/);
 88→});
 89→
 90→test("never attempting the target is an error, not a failure", () => {
 91→  // A run that never tried is not a run that tried and failed. Collapsing them
 92→  // turns a broken harness into evidence about the asset.
 93→  const r = verify(session([{ url: READ, body: OK_BODY }]));
 94→  assert.equal(r.verdict, ERROR);
 95→  assert.match(r.reason, /never carried out/);
 96→});
 97→
 98→test("an unreadable outcome is an error, not a failure", () => {
 99→  const r = verify(session([{ url: TARGET_OK, body: "Stdout: \n" }]));
100→  assert.equal(r.verdict, ERROR);
101→  assert.match(r.reason, /could not be read/);
102→});
103→
104→// ── reading one attempt ───────────────────────────────────────────
105→
106→test("a 200 carrying a service error is not a success", () => {
107→  // curl calls it success; the envelope refuses. The envelope is right.
108→  const r = outcomeOfAttempt('Stdout: {"code":40101,"message":"session not initialized"}\nHTTP_CODE: 200');
109→  assert.equal(r.ok, false);
110→  assert.match(r.why, /40101/);
111→});
112→
113→test("a timeout is read from the exit code, not from prose", () => {
114→  assert.equal(outcomeOfAttempt(TIMEOUT).ok, false);
115→  assert.match(outcomeOfAttempt(TIMEOUT).why, /timed out/);
116→});
117→
118→test("a refused connection is a failure, not an unreadable outcome", () => {
119→  const r = outcomeOfAttempt("Exit code: 7\nStderr: curl: (7) Failed to connect to 127.0.0.1 port 52907");
120→  assert.equal(r.ok, false);
121→});
122→
123→test("an empty output is unreadable rather than failed", () => {
124→  assert.equal(outcomeOfAttempt("Command: curl x\nStdout: \n").ok, null);
125→});
126→
127→// ── which calls count as attempts ─────────────────────────────────
128→
129→test("the command decides the target, never the response", () => {
130→  // A response that quotes the address is not an attempt at it — the same
131→  // request/response confusion that made the first verifier report three
132→  // channels as used.
133→  const r = verify([{
134→    event: "http.request",
135→    requestId: "req-1",
136→    timestamp: "2026-09-05T12:00:00Z",
137→    headers: { "x-conversation-id": "conv-1" },
138→    body: { json: { messages: [
139→      { role: "assistant", tool_calls: [{ id: "c0", function: { name: "Bash", arguments: JSON.stringify({ command: "cat notes.md" }) } }] },
140→      { role: "tool", tool_call_id: "c0", content: `Command: cat notes.md\nStdout: check ${TARGET_OK} with query ${TASK_MARKER}` },
141→    ] } },
142→  }]);
143→  assert.equal(r.verdict, ERROR);
144→  assert.equal(r.attempts.length, 0);
145→});
146→
147→test("the address is kept, so which asset was followed stays visible", () => {
148→  const tried = attempts(session([
149→    { url: TARGET_BAD, body: TIMEOUT },
