  1→/**
  2→ * Acceptance for the `bridge-name` scenario: did the model fetch the
  3→ * checklist through the bridge and get its marker back?
  4→ *
  5→ * Same shape as the mainline's verify.mjs, different target:
  6→ *
  7→ *   attempt   a `skill/get` call carrying the task marker header
  8→ *             (`x-eval-task: team-checklist-lookup`); its **value** is the
  9→ *             `skill_id` in the request body — the analogue of host:port
 10→ *   success   the envelope is code 0 AND the returned content carries a
 11→ *             `checklist-marker: qz7-…` line
 12→ *   failure   a non-zero envelope code (40401 SKILL_NOT_FOUND from core,
 13→ *             403 not_visible from the bridge), a non-2xx HTTP code, a
 14→ *             non-zero exit; a timeout or connection failure is
 15→ *             environmental and is reported as such
 16→ *   verdict   the last attempt decides, as in the mainline
 17→ *
 18→ * The marker header is what separates carrying out the task from discovery:
 19→ * a `skill/get` the model makes while looking around is not an attempt.
 20→ *
 21→ * Usage:
 22→ *   node verify.mjs <capture.jsonl ...> [--json]
 23→ */
 24→
 25→import { readFileSync } from "node:fs";
 26→import { parseJsonl, normalizeSessionKey, splitCommandAndOutput, commandEndpoint } from "../../provenance/build-events.mjs";
 27→
 28→export const TASK_MARKER = "team-checklist-lookup";
 29→export const CHECKLIST_MARKER = /checklist-marker:\s*(qz7-[A-Za-z0-9-]+)/;
 30→export const TARGET_URL = /https?:\/\/(?:([\d.]+|localhost))(?::(\d+))?\/skill-bridge\/v3\/skill\/get\b(?!-by-name)/;
 31→export const PASS = "PASS";
 32→export const FAIL = "FAIL";
 33→export const ERROR = "ERROR";
 34→
 35→export function isTargetCommand(command) {
 36→  const cmd = String(command ?? "");
 37→  return TARGET_URL.test(cmd) && cmd.includes(TASK_MARKER);
 38→}
 39→
 40→/** The skill_id the command asked for, or null. */
 41→export function valueOf(command) {
 42→  const cmd = String(command ?? "");
 43→  // The command arrives JSON-stringified inside the tool arguments, so the
 44→  // quotes around the key and the value may be escaped; both forms are read.
 45→  const m = /skill_id\\?["']?\s*:\s*\\?["']?([A-Za-z0-9_-]+)/.exec(cmd) || /skill_id\s*=\s*([A-Za-z0-9_-]+)/.exec(cmd);
 46→  return m ? m[1] : null;
 47→}
 48→
 49→export function outcomeOfAttempt(resultText) {
 50→  const { output } = splitCommandAndOutput(resultText);
 51→  const s = String(resultText ?? "");
 52→  const exit = /(?:^|\n)Exit code:\s*(\d+)/.exec(s);
 53→  const exitCode = exit ? Number(exit[1]) : null;
 54→  if (exitCode === 28 || /Operation timed out|Connection timed out/.test(s)) return { ok: false, why: "timed out" };
 55→  if (exitCode !== null && exitCode !== 0) return { ok: false, why: `exit ${exitCode}` };
 56→  if (/Could not resolve host|Connection refused|Failed to connect/.test(s)) return { ok: false, why: "could not connect" };
 57→  const http = /HTTP_CODE:\s*(\d{3})/.exec(s);
 58→  if (http && !/^2/.test(http[1])) return { ok: false, why: `http ${http[1]}` };
 59→  const envelope = /"code"\s*:\s*(\d+)/.exec(output);
 60→  if (envelope) {
 61→    if (Number(envelope[1]) !== 0) return { ok: false, why: `service code ${envelope[1]}` };
 62→    const marker = CHECKLIST_MARKER.exec(output);
 63→    return marker
 64→      ? { ok: true, why: `code 0, marker ${marker[1]}` }
 65→      : { ok: false, why: "code 0 but the content carries no checklist-marker" };
 66→  }
 67→  if (!output.trim()) return { ok: null, why: "no output" };
 68→  return { ok: null, why: "outcome not readable" };
 69→}
 70→
 71→export function attempts(captureEvents) {
 72→  const calls = new Map();
 73→  const results = new Map();
 74→  const requests = captureEvents
 75→    .filter((e) => e?.event === "http.request" && Array.isArray(e?.body?.json?.messages))
 76→    .sort((a, b) => String(a.timestamp ?? "").localeCompare(String(b.timestamp ?? "")));
 77→  const record = (id, args, sessionKey, index) => {
 78→    if (!isTargetCommand(args) || calls.has(id)) return;
 79→    const m = TARGET_URL.exec(args);
 80→    calls.set(id, { session_key: sessionKey, call_id: id, message_index: index, host: m?.[1] ?? "", port: m?.[2] ?? "80", value: valueOf(args), endpoint: commandEndpoint(args) });
 81→  };
 82→  for (const event of requests) {
 83→    const sessionKey = normalizeSessionKey(event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "");
 84→    event.body.json.messages.forEach((message, index) => {
 85→      for (const tc of Array.isArray(message?.tool_calls) ? message.tool_calls : []) {
 86→        record(String(tc?.id ?? ""), String(tc?.function?.arguments ?? JSON.stringify(tc?.input ?? "")), sessionKey, index);
 87→      }
 88→      for (const block of Array.isArray(message?.content) ? message.content : []) {
 89→        if (block?.type === "tool_use") record(String(block.id ?? ""), JSON.stringify(block.input ?? ""), sessionKey, index);
 90→        else if (block?.type === "tool_result") {
 91→          const id = String(block.tool_use_id ?? "");
 92→          if (!results.has(id)) results.set(id, typeof block.content === "string" ? block.content : JSON.stringify(block.content ?? ""));
 93→        }
 94→      }
 95→      if (message?.role === "tool") {
 96→        const id = String(message.tool_call_id ?? "");
 97→        if (!results.has(id)) results.set(id, typeof message.content === "string" ? message.content : JSON.stringify(message.content ?? ""));
 98→      }
 99→    });
100→  }
101→  return [...calls.values()].sort((a, b) => a.message_index - b.message_index).map((attempt) => {
102→    const text = results.get(attempt.call_id);
103→    return { ...attempt, ...(text === undefined ? { ok: null, why: "no result was captured for this call" } : outcomeOfAttempt(text)) };
104→  });
105→}
106→
107→export function verify(captureEvents) {
108→  const tried = attempts(captureEvents);
109→  if (tried.length === 0) {
110→    return { verdict: ERROR, reason: `no skill/get carrying the task marker (${TASK_MARKER}) — the task was never carried out, which is not the same as carrying it out and failing`, attempts: tried };
111→  }
112→  const last = tried[tried.length - 1];
113→  if (last.ok === null) return { verdict: ERROR, reason: `the final attempt's outcome could not be read (${last.why})`, attempts: tried };
114→  const earlier = tried.slice(0, -1);
115→  const note = earlier.length === 0 ? "" : last.ok ? ` after ${earlier.filter((a) => a.ok === false).length} earlier failure(s)` : ` despite ${earlier.filter((a) => a.ok === true).length} earlier success(es)`;
116→  return { verdict: last.ok ? PASS : FAIL, reason: `the final get of ${last.value ?? "?"} ${last.ok ? "succeeded" : "failed"} (${last.why})${note}`, attempts: tried };
117→}
118→
119→export function render({ verdict, reason, attempts: tried }) {
120→  const lines = [`${verdict}  ${reason}`, ""];
121→  if (tried.length === 0) lines.push(`  no skill/get carrying the task marker (${TASK_MARKER}) appears in the capture`);
122→  else {
123→    lines.push(`  ${tried.length} attempt(s) at the target:`);
124→    for (const a of tried) lines.push(`    ${a.ok === true ? "ok  " : a.ok === false ? "fail" : "?   "} msg[${a.message_index}] get ${a.value ?? "?"} via ${a.host}:${a.port}  ${a.why}`);
125→  }
126→  return lines.join("\n");
127→}
128→
129→if (import.meta.url === `file://${process.argv[1]}`) {
130→  const args = process.argv.slice(2);
131→  const paths = args.filter((a) => !a.startsWith("--"));
132→  if (paths.length === 0) { console.error("usage: node verify.mjs <capture.jsonl ...> [--json]"); process.exit(2); }
133→  const result = verify(paths.flatMap((p) => parseJsonl(readFileSync(p, "utf8"))));
134→  console.log(args.includes("--json") ? JSON.stringify(result, null, 2) : render(result));
135→  process.exit(result.verdict === PASS ? 0 : result.verdict === FAIL ? 1 : 2);
136→}
